<template><section class="container page checkout-page"><div class="page-heading"><div><span class="eyebrow">CHECKOUT</span><h1>确认订单</h1><p>最后一步，马上送到你家。</p></div><span class="checkout-steps"><b>1</b> 确认订单　—　<span>2</span> 完成支付</span></div><div class="checkout-layout"><div><section class="checkout-card"><h3>收货地址 <button class="text-button">＋ 新增地址</button></h3><div class="address selected"><span class="radio">✓</span><div><b>林女士　138****2088</b><p>上海市静安区南京西路 888 号 鲜选公寓 12F</p></div><em>默认地址</em></div></section><section class="checkout-card"><h3>配送方式</h3><div class="delivery-options"><label class="selected"><input type="radio" checked /> <b>极速配送</b><span>预计 1 小时内送达</span><strong>¥{{shipping}}</strong></label><label><input type="radio" /> <b>预约配送</b><span>选择日期和时间段</span><strong>免费</strong></label></div></section><section class="checkout-card"><h3>商品清单</h3><div v-for="item in items" :key="item.productId" class="checkout-item"><span class="cart-thumb" :style="{background:item.product.color}">{{item.product.emoji}}</span><span><b>{{item.product.name}}</b><small>× {{item.quantity}}</small></span><strong>¥{{item.subtotal.toFixed(1)}}</strong></div></section><section class="checkout-card"><h3>备注信息</h3><input class="note-input" placeholder="给配送员留言（选填）" /></section></div><aside class="summary"><h3>支付方式</h3><label class="pay-option selected">●　微信支付 <span>推荐</span></label><label class="pay-option">○　支付宝</label><hr/><div><span>商品小计</span><b>¥{{total.toFixed(1)}}</b></div><div><span>配送费</span><b>{{shipping?'¥'+shipping:'免配送'}}</b></div><div><span>优惠券</span><b class="green">-¥0.0</b></div><div class="sum-total"><span>应付金额</span><strong>¥{{(total+shipping).toFixed(1)}}</strong></div><button class="primary full" @click="pay">提交订单并支付</button><p class="safe-tip">🔒 支付过程安全加密</p></aside></div></section></template>
<script setup>import { computed,inject } from 'vue'; import { useRouter } from 'vue-router'; import {cartItems,store} from '../data'; const router=useRouter(),notify=inject('notify'),items=cartItems,total=computed(()=>items.value.reduce((s,i)=>s+i.subtotal,0)),shipping=computed(()=>total.value>=59?0:6); const pay=()=>{store.orders.unshift({id:'FS'+Date.now().toString().slice(-8),status:'待配送',date:'2026-10-09 14:26',total:total.value+shipping.value,items:items.value.map(i=>i.productId)});store.cart.splice(0);notify('支付成功，订单已提交');router.push('/orders')}</script>
